"""Canonical language-machine construction for the policy compiler.

The pipeline is entirely userspace and single threaded:

1. one deterministic residual automaton per distinct atom.  All ``match`` atoms
   share a single prefix trie, because the residual of an exact-match language
   after a word is decided by that word's trie node (a trie is prefix
   injective), so the joint machine costs no product blow-up;
2. the joint product of trie node and non-literal residual vector, enumerated
   breadth-first from the start; the acceptance of a joint state is the rule
   matrix ``allowed(w) == some allow rule matches and no drop rule matches``;
3. Moore style partition refinement, which is monotone in the block count, so
   a compile that can no longer fit the row budget stops immediately;
4. removal of the dead residual, breadth-first renumbering in increasing
   service-label order with ``DENY`` columns ignored, and the row/cell census.

The result is the ``{'accept', 'rows', 'rows_count', 'cells'}`` image of the
contract; ``DENY`` is the target of every transition that leaves the retained
residuals and has no row of its own.
"""
from syntax import ATOM_KINDS, PolicyError

__all__ = ['DENY', 'MAX_ROWS', 'compile_rules', 'TooBig']

DENY = 4294967295
MAX_ROWS = 8192

# A joint machine this large cannot be reduced into the row budget by the
# refinement below, so the compile is abandoned instead of exhausting memory.
MAX_JOINT_STATES = 262144


class TooBig(PolicyError):
    """The compiled machine is beyond the contract's image budget."""


class _Failure(Exception):
    """Internal stop signal: the compile cannot produce a legal image."""


# --------------------------------------------------------------------------- atoms


def _collect(predicate, match_paths, nonliterals, slots, depth, deepest):
    """Register the atoms of one predicate and track its nesting depth."""
    if depth > deepest[0]:
        deepest[0] = depth
    kind = predicate[0]
    if kind in ATOM_KINDS:
        path = predicate[1]
        if kind == 'match':
            if path not in slots:
                slots[path] = len(match_paths)
                match_paths.append(path)
        else:
            key = (kind, path)
            if key not in slots:
                slots[key] = len(nonliterals)
                nonliterals.append(key)
        return
    if kind == 'not':
        _collect(predicate[1], match_paths, nonliterals, slots, depth + 1, deepest)
    else:
        _collect(predicate[1], match_paths, nonliterals, slots, depth + 1, deepest)
        _collect(predicate[2], match_paths, nonliterals, slots, depth + 1, deepest)


def _program(predicate, slots):
    """Postfix program for one predicate.

    Operands are shared atom slot numbers: the ``match`` atoms occupy
    ``0 .. len(match_paths) - 1`` and the distinct non-literal atoms follow.
    """
    program = []

    def emit(node):
        kind = node[0]
        if kind in ATOM_KINDS:
            if kind == 'match':
                program.append(slots[node[1]])
            else:
                program.append(match_count + slots[(kind, node[1])])
            return
        if kind == 'not':
            emit(node[1])
            program.append('not')
        else:
            emit(node[1])
            emit(node[2])
            program.append(kind)

    match_count = len(slots['__matches__'])
    emit(predicate)
    return program


def _evaluate(program, flags):
    stack = []
    for item in program:
        if type(item) is int:
            stack.append(flags[item])
        elif item == 'not':
            stack.append(not stack.pop())
        elif item == 'and':
            right = stack.pop()
            stack.append(stack.pop() and right)
        else:
            right = stack.pop()
            stack.append(stack.pop() or right)
    return stack[-1]


